import dynamic from 'next/dynamic';
import { useState } from 'react';

// 1. Manually Code-Split the heavy editor component.
// It will NOT be included in the initial page load bundle!
const HeavyMarkdownEditor = dynamic(() => import('./HeavyEditor'), {
  loading: () => <p>Loading editor...</p>,
  ssr: false, // Optional: Force it to only ever run on the client browser
});

export default function CommentSection() {
  const [showEditor, setShowEditor] = useState(false);

  return (
    <div>
      <button onClick={() => setShowEditor(true)}>Reply</button>

      {/* 2. The browser only downloads the Editor's JS code when this turns true! */}
      {showEditor && <HeavyMarkdownEditor />}
    </div>
  );
}
